        let currentRightPage = 1; // Page 1 starts on the right, Page 0 (left) is empty cover
        let notebookData = {};

        // Fetch the JSON dictionary generated by your Python script
        async function loadNotebook() {
            try {
                const response = await fetch('notebook_data.json');
                notebookData = await response.json();
                renderPages();
            } catch (error) {
                console.error("Failed to load Flo's notes:", error);
            }
        }

        function renderPages() {
            const leftNum = currentRightPage - 1;
            const rightNum = currentRightPage;

            // Left side: if page 0 or missing, show blank cover/empty page
            document.getElementById('left-page').innerHTML = notebookData[leftNum] 
                ? `<div>${notebookData[leftNum]}</div><div class="watermark">${leftNum}</div>` 
                : `<div><div><br><br><h1 id="title"><a href="../index.html">"The Notebook"<a></h1><br><p class="covertext">Owner: F. Blackthorn</p></div><div class="watermark"><p>---</p></div></div>`;

            // Right side: show content or empty if past the end
            document.getElementById('right-page').innerHTML = notebookData[rightNum] 
                ? `<div>${notebookData[rightNum]}</div><div class="watermark">${rightNum}</div>` 
                : `<div style="color: #aaa;"></div>`;
        }

        function turnPage(side) {
            if (side === 'right') {
                // Check if the NEXT right page exists in our dictionary before moving forward
                if (notebookData[currentRightPage + 1] !== undefined) {
                    currentRightPage += 2; // Flip a full spread (2 pages at a time)
                    renderPages();
                }
            } else if (side === 'left') {
                // Don't go lower than page 1 on the right side
                if (currentRightPage > 1) {
                    currentRightPage -= 2;
                    renderPages();
                }
            }
        }

        // Initialize on load
        loadNotebook();
